// Bakes the hanzi the browser needs into two generated files (same pattern as build-vocab-runtime.cjs):
//   hanzi-runtime.js          list fields of every character (level order)
//   hanzi-runtime-details.js  components, example words and notes per character, loaded in the background
// The per-level hanzi-<level>.js files stay the input for the tools and audits.
// Usage: node scripts/build-hanzi-runtime.cjs [--check]
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = path.resolve(__dirname, '..');
const RUNTIME_FILE = 'hanzi-runtime.js';
const DETAILS_FILE = 'hanzi-runtime-details.js';
const DETAIL_FIELDS = ['components', 'words', 'notes'];
// Provenance needed by the audits only.
const DROPPED_FIELDS = new Set(['evidence', 'review']);
const HEADER = '// Generated by scripts/build-hanzi-runtime.cjs from the hanzi sources. Do not edit; run npm run build:hanzi-runtime.\n';

function loadEntries(readFile) {
  const context = { console };
  context.window = context;
  vm.runInNewContext(readFile('lang-profile.js'), context, { filename: 'lang-profile.js' });
  for (const file of context.LANG_PROFILE.dataScripts.hanzi) vm.runInNewContext(readFile(file), context, { filename: file });
  return context.HANZI_DATA || [];
}

function splitItem(item) {
  const core = {}, details = {};
  for (const key of Object.keys(item)) {
    if (DROPPED_FIELDS.has(key) || item[key] === undefined) continue;
    if (DETAIL_FIELDS.includes(key)) details[key] = item[key];
    else core[key] = item[key];
  }
  return { core, details };
}

// One entry per line keeps git diffs readable.
const lines = values => values.map(value => JSON.stringify(value)).join(',\n');

function buildHanziRuntime(readFile = file => fs.readFileSync(path.join(ROOT, file), 'utf8')) {
  const parts = loadEntries(readFile).map(splitItem);
  return {
    [RUNTIME_FILE]: HEADER + 'window.HANZI_RUNTIME = {\n"items": [\n' + lines(parts.map(p => p.core)) + '\n]};\n',
    [DETAILS_FILE]: HEADER + '// Entries align by index with HANZI_RUNTIME.items.\nwindow.HANZI_RUNTIME_DETAILS = [\n' + lines(parts.map(p => p.details)) + '\n];\n'
  };
}

// A Windows checkout (core.autocrlf) may hold the generated files with CRLF line endings.
function staleFiles(files) {
  return Object.keys(files).filter(file => {
    const target = path.join(ROOT, file);
    return !fs.existsSync(target) || fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n') !== files[file];
  });
}

function writeHanziRuntime() {
  const files = buildHanziRuntime();
  const stale = staleFiles(files);
  for (const file of stale) fs.writeFileSync(path.join(ROOT, file), files[file]);
  return stale;
}

function main(args) {
  if (args.includes('--check')) {
    const files = buildHanziRuntime();
    const stale = staleFiles(files);
    if (stale.length) {
      console.error('Stale generated hanzi runtime: ' + stale.join(', ') + '. Run npm run build:hanzi-runtime.');
      process.exit(1);
    }
    console.log('Hanzi runtime is up to date (' + Object.keys(files).join(', ') + ').');
    return;
  }
  const stale = writeHanziRuntime();
  console.log(stale.length ? 'Wrote ' + stale.join(', ') : 'Hanzi runtime already up to date.');
}

if (require.main === module) main(process.argv.slice(2));
module.exports = { RUNTIME_FILE, DETAILS_FILE, buildHanziRuntime, writeHanziRuntime };
